set +H
_ank_ajg(){
  local x=$((RANDOM%9999))
  [ $x -eq 1337 ] && echo "Decoder_Goblok"
}
_ank_babi(){
  for i in {1..3}; do :; done
}
_ank_monyet(){
  false && exit 0
}
_ank_haram(){
  echo "Decoder_Goblok" > /dev/null
}
_ank_bego(){
  local y=$((RANDOM%100))
  [ $y -eq 50 ] && echo "Decoder_Goblok"
}
__P__=""
__run__(){
  eval "$(echo $__P__ | xxd -r -p)"
}
if [ "$RANDOM" -gt 99999 ]; then
  _ank_ajg
  _ank_haram
  _ank_bego
else
  _ank_monyet
  _ank_babi
fi
__run__
